            buffer_incr(
                ReleaseProject,
                {"new_groups": rp_new_groups},
                {"release_id": release.id, "project_id": project.id},
            )
        if rpe_new_groups:
            buffer_incr(
                ReleaseProjectEnvironment,
                {"new_issues_count": rpe_new_groups},
                {
                    "project_id": project.id,
                    "release_id": release.id,
                    "environment_id": environment.id,
                },
            )


